INSERT INTO `questions` (`questions_id`, `question_text`, `question_type`, `points`, `question_order`, `created_at`, `users_id`, `lessons_id`) VALUES
(1, 'What is the recommended frequency of using DEO GO deodorant?', 'multiple_choice', 2, 1, '2026-02-17 17:07:19', 4, NULL),
(2, 'What is the purpose of the antimicrobial agent in DEO GO deodorant?', 'multiple_choice', 2, 2, '2026-02-17 17:07:19', 4, NULL),
(3, 'What is the recommended storage condition for DEO GO deodorant?', 'multiple_choice', 2, 3, '2026-02-17 17:07:19', 4, NULL),
(4, 'What should you do in case of accidental contact of DEO GO deodorant with your eyes?', 'multiple_choice', 2, 4, '2026-02-17 17:07:19', 4, NULL),
(5, 'What is the shelf-life of DEO GO deodorant when stored properly?', 'multiple_choice', 2, 5, '2026-02-17 17:07:19', 4, NULL),
(6, 'DEO GO deodorant is suitable for use on broken, irritated, or freshly shaved skin.', 'true_false', 1, 6, '2026-02-17 17:07:19', 4, NULL),
(7, 'The product should be applied to clean, dry underarm skin.', 'true_false', 1, 7, '2026-02-17 17:07:19', 4, NULL),
(8, 'DEO GO deodorant contains moisturizing ingredients.', 'true_false', 1, 8, '2026-02-17 17:07:19', 4, NULL),
(9, 'You should use a thick layer of DEO GO deodorant for optimal results.', 'true_false', 1, 9, '2026-02-17 17:07:19', 4, NULL),
(10, 'DEO GO deodorant is not suitable for everyday use.', 'true_false', 1, 10, '2026-02-17 17:07:19', 4, NULL),
(11, 'According to recent studies, what is one of the main reasons students perceive AI as helpful in academic writing?', 'multiple_choice', 2, 1, '2026-02-18 12:57:04', 4, NULL),
(12, 'What is one of the concerns raised by researchers regarding excessive reliance on AI tools in academic writing?', 'multiple_choice', 2, 2, '2026-02-18 12:57:04', 4, NULL),
(13, 'What is the primary goal of the study mentioned in the content regarding the effects of social media on social behavior?', 'multiple_choice', 2, 3, '2026-02-18 12:57:04', 4, NULL),
(14, 'According to the study, what is one of the limitations of the research regarding social media use and social behavior?', 'multiple_choice', 2, 4, '2026-02-18 12:57:04', 4, NULL),
(15, 'What is the significance of the study for school administrators?', 'multiple_choice', 2, 5, '2026-02-18 12:57:04', 4, NULL),
(16, 'orm for Grade 12 students\nANSWER: B\n\nMC4: According to the study, what is one of the limitations of the research regarding social media use and social behavior?\nA) Limited sample size\nB) Only self-reported data from survey questionnaires\nC) Exclusion of students from other grade levels\nD) All of the above\nANSWER: D\n\nMC5: What is the significance of the study for school administrators?\nA) To develop policies or programs on proper social media use\nB) To promote positive social interaction among students\nC) To improve communication between teachers and students\nD) To increase funding for technology in schools\nANSWER: A\n\nTRUE/FALSE QUESTIONS:\n\nTF1: The study aims to determine the effects of social media on the social behavior of Grade 12 students.', 'true_false', 1, 6, '2026-02-18 12:57:04', 4, NULL),
(17, 'The study includes students from other grade levels in addition to Grade 12 students.', 'true_false', 1, 7, '2026-02-18 12:57:04', 4, NULL),
(18, 'The study focuses solely on the social behavior of students and does not cover other aspects such as academic performance.', 'true_false', 1, 8, '2026-02-18 12:57:04', 4, NULL),
(19, 'The study uses both self-reported data from survey questionnaires and interviews and observations.', 'true_false', 1, 9, '2026-02-18 12:57:04', 4, NULL),
(20, 'The study may serve as a reference for future studies related to social media and student behavior.', 'true_false', 1, 10, '2026-02-18 12:57:04', 4, NULL),
(21, 'What is the primary purpose of the study \"FRIENDS OR FOE? A Case Study on Students’ Attitudes Toward Artificial Intelligence in Academic Writing\"?', 'multiple_choice', 2, 1, '2026-02-20 14:35:42', 4, NULL),
(22, 'According to the study, what are some of the benefits that students perceive from using AI in academic writing?', 'multiple_choice', 2, 2, '2026-02-20 14:35:42', 4, NULL),
(23, 'What are some potential concerns raised by researchers regarding the use of AI in academic writing?', 'multiple_choice', 2, 3, '2026-02-20 14:35:42', 4, NULL),
(24, 'What is the scope of the study, as mentioned in the research proposal?', 'multiple_choice', 2, 4, '2026-02-20 14:35:42', 4, NULL),
(25, 'Why is the study significant, according to the research proposal?', 'multiple_choice', 2, 5, '2026-02-20 14:35:42', 4, NULL),
(26, 'The study aims to measure the effectiveness of AI tools in improving writing quality, grammar accuracy, or academic performance.', 'true_false', 1, 6, '2026-02-20 14:35:42', 4, NULL),
(27, 'According to the study, some students use AI tools as a replacement for their own thinking.', 'true_false', 1, 7, '2026-02-20 14:35:42', 4, NULL),
(28, 'The study is significant as it provides valuable insights into the growing role of Artificial Intelligence in academic writing.', 'true_false', 1, 8, '2026-02-20 14:35:42', 4, NULL),
(29, 'The study is limited to students from other grade levels and schools in Bugang Integrated School.', 'true_false', 1, 9, '2026-02-20 14:35:42', 4, NULL),
(30, 'The study helps students reflect on their own attitudes and practices regarding the use of Artificial Intelligence in academic writing.', 'true_false', 1, 10, '2026-02-20 14:35:42', 4, NULL),
