(1, 'According to recent studies, what is one of the main reasons students perceive AI as helpful in academic writing?', 'multiple_choice', 2, 1, NULL, 4, 'public', 3, '2026-02-18 12:57:04', '2026-02-20 14:37:04'),
(2, 'What is one of the concerns raised by researchers regarding excessive reliance on AI tools in academic writing?', 'multiple_choice', 2, 1, NULL, 4, 'public', 3, '2026-02-18 12:57:04', '2026-02-20 14:37:04'),
(3, 'What is the primary goal of the study mentioned in the content regarding the effects of social media on social behavior?', 'multiple_choice', 2, 1, NULL, 4, 'public', 3, '2026-02-18 12:57:04', '2026-02-20 14:37:04'),
(4, 'According to the study, what is one of the limitations of the research regarding social media use and social behavior?', 'multiple_choice', 2, 1, NULL, 4, 'public', 3, '2026-02-18 12:57:04', '2026-02-20 14:37:04'),
(5, 'What is the significance of the study for school administrators?', 'multiple_choice', 2, 1, NULL, 4, 'public', 3, '2026-02-18 12:57:04', '2026-02-20 14:37:04'),
(6, 'orm for Grade 12 students\nANSWER: B\n\nMC4: According to the study, what is one of the limitations of the research regarding social media use and social behavior?\nA) Limited sample size\nB) Only self-reported data from survey questionnaires\nC) Exclusion of students from other grade levels\nD) All of the above\nANSWER: D\n\nMC5: What is the significance of the study for school administrators?\nA) To develop policies or programs on proper social media use\nB) To promote positive social interaction among students\nC) To improve communication between teachers and students\nD) To increase funding for technology in schools\nANSWER: A\n\nTRUE/FALSE QUESTIONS:\n\nTF1: The study aims to determine the effects of social media on the social behavior of Grade 12 students.', 'true_false', 1, 1, NULL, 4, 'public', 3, '2026-02-18 12:57:04', '2026-02-20 14:37:04'),
(7, 'The study includes students from other grade levels in addition to Grade 12 students.', 'true_false', 1, 1, NULL, 4, 'public', 3, '2026-02-18 12:57:04', '2026-02-20 14:37:04'),
(8, 'The study focuses solely on the social behavior of students and does not cover other aspects such as academic performance.', 'true_false', 1, 1, NULL, 4, 'public', 3, '2026-02-18 12:57:04', '2026-02-20 14:37:04'),
(9, 'The study uses both self-reported data from survey questionnaires and interviews and observations.', 'true_false', 1, 1, NULL, 4, 'public', 3, '2026-02-18 12:57:04', '2026-02-20 14:37:04'),
(10, 'The study may serve as a reference for future studies related to social media and student behavior.', 'true_false', 1, 1, NULL, 4, 'public', 3, '2026-02-18 12:57:04', '2026-02-20 14:37:04'),
