(549, 196, 'DEO GO deodorant is a daily-use product designed to help control body odor and keep users feeling fresh and confident throughout the day. Its key benefits include neutralizing odor-causing bacteria, providing long-lasting freshness, and being gentle on the skin. The product contains antimicrobial agents, absorbent ingredients, emollients, and fragrance, which work together to help manage moisture, maintain skin softness, and prevent irritation. To use DEO GO deodorant effectively, users should apply a thin, even layer to clean, dry underarm skin, allow the product to dry before dressing, and use it once daily or as needed. It is essential to follow the usage instructions and precautions, such as avoiding contact with eyes and not using the product on broken or irritated skin. By following these guidelines, users can enjoy the benefits of DEO GO deodorant and maintain good skin health.', 1, 1, '2026-04-20 10:19:13');

